      var table = document.querySelector('#tabla-demo');

      document.addEventListener('DOMContentLoaded', () => 
      {
          table = document.querySelector('#tabla-demo');
      });

      function copyData()
      {
          navigator.clipboard.writeText(JSON.stringify(document.querySelector('#tabla-demo').DataArray)).then(()=>{
              console.log('¡Datos copiados al portapapeles!');
          }, ()=> {
              console.log('¡Ocurrió un error al copiar los datos!');
          });
      }
      function viewTree(tree=true)
      {
          table.ShowAsTree = tree;
          table._printTreeData();
      }
      function expand()
      {
          table.ExpandRow();
      }
      function collapse()
      {
          table.CollapseRow();
      }
      function addIdent(add=true)
      {
          const row = table.GetTrByIndex(table.CurrentRowIndex());
          table.RowIndent(row, add);
      }
